command:
/**
 * DarkSpace Job Generator
 * Sequentially queries the 6 Job Generator tables to produce a complete mission briefing.
 */
const pack = game.packs.get("darkspace.rollable-tables");
if (!pack) {
  ui.notifications.error("DarkSpace rollable-tables pack not found.");
} else {
  const tables = [
    { id: "dsTabJobEmployer", label: "Employer" },
    { id: "dsTabJobType000",  label: "Job Type" },
    { id: "dsTabJobScope00",   label: "Scope" },
    { id: "dsTabJobLocation", label: "Location" },
    { id: "dsTabJobInvolve0", label: "Involving" },
    { id: "dsTabJobTarget00", label: "Target / Asset" }
  ];

  const results = {};
  for (const t of tables) {
    const table = await pack.getDocument(t.id);
    if (table) {
      const drawn = await table.draw({ displayChat: false });
      results[t.label] = drawn.results[0]?.text || drawn.results[0]?.description || "Unknown";
    } else {
      results[t.label] = "Standard";
    }
  }

  const rewardRoll = await new Roll("2d6 * 500").evaluate();
  const contractId = "JOB-" + Math.floor(1000 + Math.random() * 9000);

  const content = `
    <div style="border: 1px solid #4a90e2; background: rgba(10, 20, 35, 0.95); color: #e0e6ed; padding: 12px; border-radius: 6px; font-family: monospace;">
      <div style="border-bottom: 1px solid #4a90e2; padding-bottom: 6px; margin-bottom: 8px;">
        <span style="float: right; color: #ffb74d;"><b>CR: ${rewardRoll.total.toLocaleString()} Cr</b></span>
        <b style="color: #4a90e2; font-size: 1.1em;">ENCRYPTED CONTRACT: ${contractId}</b>
      </div>
      <table style="width: 100%; border: none; font-size: 0.95em;">
        <tr><td style="width: 30%; color: #81d4fa;"><b>Employer:</b></td><td>${results["Employer"]}</td></tr>
        <tr><td style="color: #81d4fa;"><b>Mission Type:</b></td><td>${results["Job Type"]}</td></tr>
        <tr><td style="color: #81d4fa;"><b>Scale / Scope:</b></td><td>${results["Scope"]}</td></tr>
        <tr><td style="color: #81d4fa;"><b>Target Theater:</b></td><td>${results["Location"]}</td></tr>
        <tr><td style="color: #81d4fa;"><b>Key Contact:</b></td><td>${results["Involving"]}</td></tr>
        <tr><td style="color: #81d4fa;"><b>Objective:</b></td><td>${results["Target / Asset"]}</td></tr>
      </table>
      <div style="margin-top: 10px; padding-top: 6px; border-top: 1px dashed #37474f; font-size: 0.85em; color: #90a4ae;">
        <i>Standard mercenary disclaimer applies. Failure to execute within 30 solar cycles incurs penalty fees.</i>
      </div>
    </div>
  `;

  await ChatMessage.create({
    user: game.user._id,
    speaker: { alias: "Guild Contract Terminal" },
    content: content
  });
}
